import type { sheets_v4 } from 'googleapis';

export type FieldType = 'string' | 'number' | 'boolean' | 'json';

export interface FieldSpec {
  key: string;
  type: FieldType;
  /** Empty cell maps to `undefined` on this field instead of '' / 0 / false. */
  optional?: boolean;
}

const COLUMN_LETTERS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
function columnLetter(index: number): string {
  if (index < 26) return COLUMN_LETTERS[index]!;
  return COLUMN_LETTERS[Math.floor(index / 26) - 1]! + COLUMN_LETTERS[index % 26]!;
}

/**
 * Generic "one entity type = one tab, one row per record" mapping on top of
 * the Sheets API. Complex/nested fields (arrays, nested objects) are stored
 * JSON-stringified in a single cell - readable via the API, not meant to be
 * hand-edited as a "nice" spreadsheet for those columns. Simple fields
 * (name, branch, year, ...) are plain cells a human can edit directly.
 *
 * This is intentionally *not* optimized for large datasets: every write
 * that needs a specific row (update/remove) first re-reads the whole tab to
 * find that row's current sheet position. Fine for the row counts a college
 * exam roster or room list actually has; not a fit for anything sheet-sized
 * for AllocationResult-scale JSON blobs at 1,000+ students (see repositories
 * that use this - allocation storage in Sheets is flagged as not
 * recommended for that reason).
 */
export class SheetTable<T extends { id: string }> {
  private sheetIdCache: number | null = null;

  constructor(
    private readonly sheets: sheets_v4.Sheets,
    private readonly spreadsheetId: string,
    private readonly tabName: string,
    private readonly fields: FieldSpec[]
  ) {}

  private get lastColumn(): string {
    return columnLetter(this.fields.length - 1);
  }

  /** Creates the tab with a header row if it doesn't already exist. Idempotent. */
  async ensureExists(): Promise<void> {
    const meta = await this.sheets.spreadsheets.get({ spreadsheetId: this.spreadsheetId });
    const existing = meta.data.sheets?.find((s) => s.properties?.title === this.tabName);
    if (existing) {
      this.sheetIdCache = existing.properties?.sheetId ?? null;
      return;
    }
    const res = await this.sheets.spreadsheets.batchUpdate({
      spreadsheetId: this.spreadsheetId,
      requestBody: { requests: [{ addSheet: { properties: { title: this.tabName } } }] },
    });
    this.sheetIdCache = res.data.replies?.[0]?.addSheet?.properties?.sheetId ?? null;
    await this.sheets.spreadsheets.values.update({
      spreadsheetId: this.spreadsheetId,
      range: `${this.tabName}!A1:${this.lastColumn}1`,
      valueInputOption: 'RAW',
      requestBody: { values: [this.fields.map((f) => f.key)] },
    });
  }

  private async getSheetId(): Promise<number> {
    if (this.sheetIdCache !== null) return this.sheetIdCache;
    await this.ensureExists();
    if (this.sheetIdCache === null) throw new Error(`Could not resolve sheetId for tab "${this.tabName}"`);
    return this.sheetIdCache;
  }

  private rowToObject(row: string[]): T {
    const obj: Record<string, unknown> = {};
    this.fields.forEach((field, i) => {
      const cell = row[i] ?? '';
      if (cell === '' && field.optional) {
        obj[field.key] = undefined;
        return;
      }
      switch (field.type) {
        case 'number':
          obj[field.key] = cell === '' ? undefined : Number(cell);
          break;
        case 'boolean':
          obj[field.key] = cell === 'true';
          break;
        case 'json':
          obj[field.key] = cell === '' ? undefined : JSON.parse(cell);
          break;
        default:
          obj[field.key] = cell;
      }
    });
    return obj as T;
  }

  private objectToRow(obj: T): string[] {
    const record = obj as unknown as Record<string, unknown>;
    return this.fields.map((field) => {
      const value = record[field.key];
      if (value === undefined || value === null) return '';
      if (field.type === 'json') return JSON.stringify(value);
      return String(value);
    });
  }

  /** Returns every record with its 1-based sheet row number (header = row 1). */
  private async getAllWithRowNumbers(): Promise<Array<{ rowNumber: number; obj: T }>> {
    await this.ensureExists();
    const res = await this.sheets.spreadsheets.values.get({
      spreadsheetId: this.spreadsheetId,
      range: `${this.tabName}!A2:${this.lastColumn}`,
    });
    const rows = res.data.values ?? [];
    const out: Array<{ rowNumber: number; obj: T }> = [];
    rows.forEach((row, i) => {
      const idCell = row[0];
      if (!idCell) return; // skip blank/deleted rows
      out.push({ rowNumber: i + 2, obj: this.rowToObject(row as string[]) });
    });
    return out;
  }

  async getAll(): Promise<T[]> {
    return (await this.getAllWithRowNumbers()).map((r) => r.obj);
  }

  async getById(id: string): Promise<T | undefined> {
    return (await this.getAll()).find((o) => o.id === id);
  }

  async create(obj: T): Promise<T> {
    await this.ensureExists();
    await this.sheets.spreadsheets.values.append({
      spreadsheetId: this.spreadsheetId,
      range: `${this.tabName}!A1:${this.lastColumn}1`,
      valueInputOption: 'RAW',
      insertDataOption: 'INSERT_ROWS',
      requestBody: { values: [this.objectToRow(obj)] },
    });
    return obj;
  }

  async createMany(objs: T[]): Promise<T[]> {
    if (objs.length === 0) return objs;
    await this.ensureExists();
    await this.sheets.spreadsheets.values.append({
      spreadsheetId: this.spreadsheetId,
      range: `${this.tabName}!A1:${this.lastColumn}1`,
      valueInputOption: 'RAW',
      insertDataOption: 'INSERT_ROWS',
      requestBody: { values: objs.map((o) => this.objectToRow(o)) },
    });
    return objs;
  }

  async update(id: string, patch: Partial<T>): Promise<T> {
    const rows = await this.getAllWithRowNumbers();
    const match = rows.find((r) => r.obj.id === id);
    if (!match) throw new Error(`Record ${id} not found in tab "${this.tabName}"`);
    const updated = { ...match.obj, ...patch, id } as T;
    await this.sheets.spreadsheets.values.update({
      spreadsheetId: this.spreadsheetId,
      range: `${this.tabName}!A${match.rowNumber}:${this.lastColumn}${match.rowNumber}`,
      valueInputOption: 'RAW',
      requestBody: { values: [this.objectToRow(updated)] },
    });
    return updated;
  }

  async remove(id: string): Promise<void> {
    const rows = await this.getAllWithRowNumbers();
    const match = rows.find((r) => r.obj.id === id);
    if (!match) return;
    const sheetId = await this.getSheetId();
    await this.sheets.spreadsheets.batchUpdate({
      spreadsheetId: this.spreadsheetId,
      requestBody: {
        requests: [
          {
            deleteDimension: {
              range: {
                sheetId,
                dimension: 'ROWS',
                startIndex: match.rowNumber - 1,
                endIndex: match.rowNumber,
              },
            },
          },
        ],
      },
    });
  }
}
